<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class AuthController extends Controller { private function shape(User $u):array{return ['id'=>(int)$u->id,'full_name'=>$u->full_name,'username'=>$u->username,'email'=>$u->email,'role'=>$u->role,'avatar_path'=>$u->avatar_path];} public function login(Request $r){$key=trim(strip_tags((string)$r->input('username','')));$u=User::where(fn($q)=>$q->where('username',$key)->orWhere('email',$key))->where('is_active',1)->first();if(!$u||!password_verify((string)$r->input('password',''),$u->password_hash))return response()->json(['error'=>'Invalid credentials'],401);Auth::login($u);$r->session()->regenerate();return response()->json(['data'=>$this->shape($u)]);} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['data'=>true]);} public function me(Request $r){return response()->json(['data'=>$this->shape($r->user())]);} }
